(()=>{document.body.style.cssText='margin:0;width:300px;font:16px "Times New Roman"';const out={};for(const open of [false,true]){const d=document.createElement('details');d.open=open;d.style.width='200px';d.innerHTML='<summary>Alpha</summary><div style="height:10px;width:20px"></div><div style="height:12px;width:30px"></div>';document.body.append(d);const after=document.createElement('div');after.style.height='5px';document.body.append(after);const snap=e=>{const r=e.getBoundingClientRect();return[r.y,r.width,r.height,e.getClientRects().length]};out[String(open)]=[d,...d.children,after].map(snap);const observer=new MutationObserver(()=>{});observer.observe(d,{attributes:true,attributeOldValue:true});const read=Element.prototype.getAttribute;d.getAttribute=d.setAttribute=d.removeAttribute=()=>{throw Error('author attribute method')};d.open=!open;d.open=open;out['reflection/'+open]={instance:d instanceof HTMLDetailsElement,open:d.open,attribute:read.call(d,'open')!==null,records:observer.takeRecords().map(r=>[r.attributeName,r.oldValue])};observer.disconnect();d.remove();after.remove()}return out})()